import re
from datetime import datetime

_DISPLAY_NAME_RE = re.compile(r"<([^<>]*)>")
_EXT_RE = re.compile(r"ext|x|#", re.IGNORECASE)
_ZIP_PLUS4_RE = re.compile(r"([0-9]{4,5})-[0-9]{4}")
_ZIP5_RE = re.compile(r"[0-9]{5}")
_TAG_SPLIT_RE = re.compile(r"[;,]")
_GMAIL_DOMAINS = {"gmail.com", "googlemail.com"}
_OPT_OUT_VALUES = {"y", "yes", "true", "1"}
_DATE_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")


def dedupe_contacts(rows):
    """Deduplicate CRM contact rows according to the data team's rules."""

    def field(row, key):
        value = row.get(key)
        return "" if value is None else str(value)

    # Rule 1: email normalization
    def norm_email(raw):
        s = raw
        m = _DISPLAY_NAME_RE.search(s)
        if m:
            s = m.group(1)
        s = s.strip().lower()
        if s.count("@") == 1:
            local, domain = s.split("@")
            if domain in _GMAIL_DOMAINS:
                local = local.split("+", 1)[0].replace(".", "")
                s = local + "@gmail.com"
        return s

    # Rule 2: email validity
    def email_valid(s):
        if s.count("@") != 1:
            return False
        local, domain = s.split("@")
        return (
            bool(local)
            and "." in domain
            and not domain.startswith(".")
            and not domain.endswith(".")
        )

    # Rule 3: phone normalization; returns 10-digit string or "" if invalid
    def norm_phone(raw):
        m = _EXT_RE.search(raw)
        if m:
            raw = raw[: m.start()]
        digits = "".join(ch for ch in raw if ch in "0123456789")
        if len(digits) == 11 and digits[0] == "1":
            digits = digits[1:]
        if len(digits) == 10 and digits[0] not in "01":
            return digits
        return ""

    # Rule 4: ZIP normalization
    def norm_zip(raw):
        s = raw.strip()
        m = _ZIP_PLUS4_RE.fullmatch(s)
        if m:
            s = m.group(1)
        if len(s) == 4 and s.isascii() and s.isdigit():
            s = "0" + s
        return s if _ZIP5_RE.fullmatch(s) else ""

    # Rule 5: name normalization
    def norm_name(raw):
        s = raw.strip()
        if s.isupper() or s.islower():
            s = s.title()
        return s

    # Rule 6: updated timestamp parsing
    def parse_updated(raw):
        s = raw.strip()
        for fmt in _DATE_FORMATS:
            try:
                return datetime.strptime(s, fmt)
            except ValueError:
                pass
        raise ValueError(f"Unrecognized 'updated' value: {raw!r}")

    # Normalize every row; Rule 9: drop rows lacking both valid email and phone
    records = []
    for index, row in enumerate(rows):
        email = norm_email(field(row, "email"))
        if not email_valid(email):
            email = ""
        phone = norm_phone(field(row, "phone"))
        if not email and not phone:
            continue
        source = field(row, "source").strip().lower()
        tags = {
            t.strip().lower()
            for t in _TAG_SPLIT_RE.split(field(row, "tags"))
            if t.strip()
        }
        records.append({
            "index": index,
            "first_name": norm_name(field(row, "first_name")),
            "last_name": norm_name(field(row, "last_name")),
            "email": email,
            "phone": phone,
            "zip": norm_zip(field(row, "zip")),
            "source": source,
            "is_manual": source == "manual",
            "tags": tags,
            "opted_out": field(row, "opted_out").strip().lower() in _OPT_OUT_VALUES,
            "updated": parse_updated(field(row, "updated")),
        })

    # Rule 10: transitive matching via union-find
    parent = list(range(len(records)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(i, j):
        ri, rj = find(i), find(j)
        if ri != rj:
            # keep the earlier record as root (not required, but tidy)
            if ri < rj:
                parent[rj] = ri
            else:
                parent[ri] = rj

    first_seen = {}
    for i, rec in enumerate(records):
        keys = []
        if rec["email"]:
            keys.append(("email", rec["email"]))
        if rec["phone"] and rec["last_name"]:
            keys.append(("phone", rec["phone"], rec["last_name"].casefold()))
        for key in keys:
            if key in first_seen:
                union(i, first_seen[key])
            else:
                first_seen[key] = i

    groups = {}
    for i, rec in enumerate(records):
        groups.setdefault(find(i), []).append(rec)

    # Rule 11: field selection preference
    def pick(group, key):
        candidates = [r for r in group if r[key]]
        if not candidates:
            return ""
        best = min(
            candidates,
            key=lambda r: (not r["is_manual"], -r["updated"].timestamp()
                           if False else 0, r["index"]),
        ) if False else None
        # explicit, readable ordering: manual first, newest updated, earliest row
        best = candidates[0]
        for r in candidates[1:]:
            if (r["is_manual"], r["updated"], -r["index"]) > (
                best["is_manual"], best["updated"], -best["index"]
            ):
                best = r
        return best[key]

    # Rule 12: order people by their earliest input row
    ordered = sorted(groups.values(), key=lambda g: min(r["index"] for r in g))

    output = []
    for group in ordered:
        all_tags = set()
        for r in group:
            all_tags |= r["tags"]
        output.append({
            "first_name": pick(group, "first_name"),
            "last_name": pick(group, "last_name"),
            "email": pick(group, "email"),
            "phone": pick(group, "phone"),
            "zip": pick(group, "zip"),
            "tags": ";".join(sorted(all_tags)),
            "opted_out": "Y" if any(r["opted_out"] for r in group) else "N",
            "updated": max(r["updated"] for r in group).strftime("%Y-%m-%d"),
            "source": pick(group, "source"),
        })
    return output
